  function settingsView(){return heading('本地数据与分析设置','模型分析使用示例结果；阅读、笔记与导出实际在浏览器中运行。')+`<div class="content"><div class="setting row"><div class="grow"><h3>离线模式</h3><p>本原型不发出模型请求；关闭后仅可体验授权流程。</p></div><input type="checkbox" id="offline-toggle" aria-label="离线模式" ${db.offline?'checked':''}></div><div class="setting row"><div class="grow"><h3>外部服务授权</h3><p>在发送前核对接收方、文档范围与实际片段。</p></div><button data-action="external-preview">体验授权流程</button></div><div class="setting row"><div class="grow"><h3>本地笔记与分享包</h3><p>导出文件备份；此原型格式与正式应用不兼容。</p></div><button data-action="share">导出</button><button data-action="import-bundle">导入</button></div><div class="setting row"><div class="grow"><h3>重置 v2 演示</h3><p>清除本版笔记与导入文本，不影响 v1 或正式应用。</p></div><button data-action="reset">重置</button></div><div class="notice" style="margin-top:20px">PDF 页面由随附真实PDF文件预先渲染；文字坐标取自PDFium。没有通用浏览器PDF解析器、Embedding或大模型。4B/8B效果和性能仍需PoC验证。</div></div>`;}
  function tasksView(){return heading('后台任务','任务进度、取消与失败重试是交互演示，不执行真实模型推理。',`<button data-action="demo-failure">演示任务失败</button>`)+`<div class="content">${db.jobs.length?db.jobs.map(j=>`<article class="job"><div class="row between"><h3>${esc(j.name)}</h3>${tag(j.status,j.status==='执行失败'?'amber':j.status==='已完成'?'green':'blue')}</div><div class="progress"><span style="width:${j.progress}%"></span></div><div class="row between"><small>${j.progress}% · ${esc(j.detail||'预置分析演示，旧结果保留')}</small>${j.status==='执行中'?`<button class="small" data-cancel="${j.id}">取消任务</button>`:['已取消','执行失败'].includes(j.status)?`<button class="small" data-retry="${j.id}">重试</button>`:`<button class="small" data-tab="${j.target||'table'}">查看结果</button>`}</div></article>`).join(''):'<div class="notice">尚未发起演示任务。可以从文档库“发现关联”，或在对照表“开始提取”。</div>'}</div>`;}
  function modal(title,body,footer=''){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="quiet small" data-action="close-dialog" aria-label="关闭对话框">${icon('close')}</button></div><div class="dialog-body">${body}</div><div class="dialog-foot"><button data-action="close-dialog">取消</button>${footer}</div>`;if(!d.open)d.showModal();}
