  function startNote(refs=[]){if(db.notes.length>=100)return toast('原型最多保存100条笔记，请先导出备份');pendingRef=refs;modal(refs.length?'摘录并写笔记':'创建自由笔记',`${refs.map(r=>`<small>${esc(getDoc(r.doc)?.title)} ${r.page?`/ 第 ${r.page} 页`:''}</small><blockquote>${esc(r.quote)}</blockquote>`).join('')}<label class="field">标题<input id="annotation-title" maxlength="100" value="${refs.length?'原文阅读笔记':'自由研究笔记'}"></label><label class="field">Markdown 笔记<textarea id="annotation-body" maxlength="20000" rows="5" placeholder="记录你的理解、问题或比较判断"></textarea></label>`, `<button class="primary" data-action="save-note">保存笔记</button>`);}
  function saveNewNote(){const title=$('#annotation-title').value.trim(),body=$('#annotation-body').value;if(!title)return toast('请输入笔记标题');const n={id:'note-'+Date.now(),title,body,citations:clone(pendingRef||[])};db.notes.unshift(n);activeNote=n.id;persist();close();render();toast('笔记已保存，可在研究笔记中回到这段原文');}
  function captureSelection(){if(page!=='analysis'||tab!=='reader')return;const s=window.getSelection();if(!s||s.isCollapsed||!s.rangeCount)return;const range=s.getRangeAt(0),anchor=(s.anchorNode?.nodeType===1?s.anchorNode:s.anchorNode?.parentElement)?.closest('.reader-pane'),focus=(s.focusNode?.nodeType===1?s.focusNode:s.focusNode?.parentElement)?.closest('.reader-pane');if(!anchor||anchor!==focus)return;const slot=+anchor.dataset.pane,p=panes[slot],d=getDoc(p.doc);let quote=norm(s.toString());if(!quote||quote.length>10000)return;const words=[...anchor.querySelectorAll('.pdf-word')].filter(w=>{try{return range.intersectsNode(w);}catch{return false;}});if(d.pdf&&words.length){const first=words[0],last=words.at(-1);const exact=norm(words.map(w=>w.textContent).join(''));if(!norm(fullText(d)).includes(exact))return;quote=exact;selection={doc:d.id,page:+first.dataset.page,pageEnd:+last.dataset.page,block:first.dataset.block===''?null:+first.dataset.block,wordStart:+first.dataset.word,wordEnd:+last.dataset.word,quote,sha256:d.pdf.sha256};}else if(!d.pdf&&norm(fullText(d)).includes(quote)){selection={doc:d.id,page:1,block:0,quote};}else return;$$('.pane-note-bar').forEach(el=>el.classList.remove('visible'));$(`[data-selection-bar="${slot}"]`).classList.add('visible');}
  document.addEventListener('pointerup',()=>setTimeout(captureSelection,0));document.addEventListener('keyup',captureSelection);
