    if(a==='save-cell'){const[row,id]=selectedCell.split(':'),r=db.dimensions.find(r=>r.id===row),i=['a','b','c'].indexOf(id),value=$('#edited-value').value.trim();if(!value)return toast('请输入明确结果或未找到');r.values[i]=value;r.status[i]='人工修正';persist();close();return render();}
