  document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();query=$('#query').value.trim();render();}});
  document.addEventListener('input',e=>{if(['note-title','note-body'].includes(e.target.id)){const n=db.notes.find(n=>n.id===activeNote);if(!n)return;n[e.target.id==='note-title'?'title':'body']=e.target.value;dirty=true;status();clearTimeout(saveTimer);saveTimer=setTimeout(persist,600);}});
