  $('#import-files').addEventListener('change',async e=>{let imported=0;for(const f of e.target.files){try{if(!/\.(md|markdown|txt)$/i.test(f.name)||f.size>500000||db.imported.length>=26)throw Error('仅支持500KB以内MD/TXT，合计最多30份');const text=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer()).slice(0,100000);if(db.imported.some(d=>d.title===f.name&&d.blocks[0].text===text)){toast('已跳过重复文件');continue;}const id='local-'+Date.now()+'-'+imported;db.imported.push({id,title:f.name,author:'本地导入',format:/\.txt$/i.test(f.name)?'TXT':'MD',blocks:[{id:0,page:1,text}]});scope.push(id);imported++;}catch(error){toast(error.message);}}persist();e.target.value='';go('library');toast(`已导入${imported}份文本，可完整阅读导入范围并字面检索`);});
